use vstd::prelude::*;
use vstd::vec::*;

verus! {

/// Returns a boolean vector where each element indicates whether the corresponding
/// elements in the two input vectors are not equal.
///
/// # Specification
/// - Requires: The input vectors have the same length
/// - Ensures: The result vector has the same length as the input vectors
/// - Ensures: For every valid index i, result[i] == true iff a[i] != b[i]
/// - Ensures: The result vector contains only boolean values
fn not_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires
        a.len() == b.len(),
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i && i < a.len() ==> #[trigger] result.index(i) == (a[i] != b[i]),
{
    let mut result_vec = Vec::new();
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            i <= a.len(),
            result_vec.len() == i,
            forall|j: int| 0 <= j && j < i ==> #[trigger] result_vec.index(j) == (a[j] != b[j]),
    {
        let not_eq = a[i] != b[i];
        result_vec.push(not_eq);
        i = i + 1;
    }
    
    result_vec
}

} // verus!